#ifndef TTYD_MOD_LOOSE_H
#define TTYD_MOD_LOOSE_H

/* C's argument conversions for a ported GameCube mod's calls into the game
 * (C++). The mods were written against their own prototypes: an int where
 * the decomp has an enum, their own enum or struct names, bool for BOOL, a
 * pointer where the decomp passes a small struct by value (the PowerPC ABI
 * passed it by address, so the mods declared it that way). C++ refuses
 * those calls; for each game function, ttyd_mod/game_loose.h (generated by
 * tools/port/gen_game_all.py) adds an overload that takes any arguments the
 * function itself doesn't and converts each as C (or that ABI) did. A call
 * the function accepts as it is never reaches it. */

#ifdef __cplusplus
#include <cstddef>
#include <cstdint>
#include <tuple>
#include <type_traits>
#include <utility>

template <typename P, typename A>
inline P ttydLooseArg(A&& a) {
    using D = std::decay_t<A>;
    if constexpr (std::is_convertible_v<A&&, P>) {
        return static_cast<P>(std::forward<A>(a));
    } else if constexpr (std::is_class_v<P> && std::is_pointer_v<D>) {
        const D p = a; // a struct passed by address, as on the GameCube
        return *reinterpret_cast<const P*>(p);
    } else if constexpr (std::is_class_v<P> && std::is_class_v<D>) {
        static_assert(sizeof(P) == sizeof(D), "a struct argument of another size");
        return *reinterpret_cast<const P*>(&a);
    } else {
        return (P)(a); // int and enum, pointer and pointer: as C
    }
}

/* A game struct's field seen as the type the mod gave it (the same size:
 * its own enum for the decomp's s16, its Vec3 for the decomp's Vec), as C
 * let it mix them. tools/port/mod_fields.py writes these. */
template <typename T, typename U>
inline auto& ttydAs(U& u) {
    using R = std::conditional_t<std::is_const_v<U>, const T, T>;
    return *(R*)(&u);
}
template <typename T, typename U>
inline const T& ttydAs(const U&& u) {
    return *(const T*)(&u);
}

/* A value's bytes as the GameCube (big-endian) held them: a mod's
 * `reinterpret_cast<uint8_t *>(&color)` of a 0xRRGGBBAA word, passed for a
 * GXColor, is R, G, B, A there and A, B, G, R here. For the length of the
 * call it's an argument of (tools/port/mod_headers.py writes these). */
template <typename T>
struct TtydBytesBE {
    uint8_t b[sizeof(T)];
    operator const uint8_t*() const {
        return b;
    }
    operator uint8_t*() {
        return b;
    }
};
template <typename T>
inline TtydBytesBE<T> ttydBytesBE(const T& v) {
    TtydBytesBE<T> out;
    const uint8_t* p = reinterpret_cast<const uint8_t*>(&v);
    for (std::size_t i = 0; i < sizeof(T); i++) {
        out.b[i] = p[sizeof(T) - 1 - i];
    }
    return out;
}

/* Part of a larger integer field as the mod split it: the GameCube is
 * big-endian, so the low word of an s64 the mod read at +4 is at +0 here.
 * OFF is the part's byte offset on this (little-endian) machine. */
template <typename T, int OFF, typename U>
inline auto& ttydPart(U& u) {
    using R = std::conditional_t<std::is_const_v<U>, const T, T>;
    return *(R*)(reinterpret_cast<std::conditional_t<std::is_const_v<U>, const char, char>*>(&u) + OFF);
}

/* The argument a parameter takes, as the PowerPC ABI passed them: floats in
 * their own registers, apart from the integers and pointers, so a mod could
 * declare `f(float scale, Vec* pos)` for the game's `f(Vec* pos, f32 scale)`.
 * Parameter i takes the argument of its class (float or not) of the same
 * rank; when the classes don't count the same, the argument in its place. */
template <typename T>
inline constexpr bool ttydIsFloat = std::is_floating_point_v<std::remove_cvref_t<T>>;

template <typename Params, typename Args>
struct TtydAbiOrder;
template <typename... P, typename... A>
struct TtydAbiOrder<std::tuple<P...>, std::tuple<A...>> {
    static constexpr std::size_t arg(std::size_t i) {
        constexpr bool pf[] = {ttydIsFloat<P>..., false};
        constexpr bool af[] = {ttydIsFloat<A>..., false};
        constexpr std::size_t n = sizeof...(P);
        std::size_t pfc = 0, afc = 0;
        for (std::size_t k = 0; k < n; k++) {
            pfc += pf[k];
            afc += af[k];
        }
        if (pfc != afc) {
            return i;
        }
        std::size_t rank = 0;
        for (std::size_t k = 0; k < i; k++) {
            rank += pf[k] == pf[i];
        }
        for (std::size_t j = 0; j < n; j++) {
            if (af[j] == pf[i] && rank-- == 0) {
                return j;
            }
        }
        return i;
    }
};

template <typename F>
struct TtydLoose;
template <typename R, typename... P>
struct TtydLoose<R (*)(P...)> {
    static constexpr std::size_t arity = sizeof...(P);
    template <typename... A>
    static R call(R (*f)(P...), A&&... a) {
        return order<A...>(f, std::index_sequence_for<P...>{}, std::forward_as_tuple(std::forward<A>(a)...));
    }
    template <typename... A, std::size_t... I, typename T>
    static R order(R (*f)(P...), std::index_sequence<I...>, T&& args) {
        using O = TtydAbiOrder<std::tuple<P...>, std::tuple<A...>>;
        return f(ttydLooseArg<P>(std::get<O::arg(I)>(std::move(args)))...);
    }
};

#define TTYD_LOOSE(name)                                                                       \
    using ttyd_fn_##name = decltype(&name);                                                    \
    template <typename... A>                                                                   \
        requires(sizeof...(A) == TtydLoose<ttyd_fn_##name>::arity &&                           \
                 !std::is_invocable_v<ttyd_fn_##name, A...>)                                   \
    inline decltype(auto) name(A&&... a) {                                                     \
        return TtydLoose<ttyd_fn_##name>::call(static_cast<ttyd_fn_##name>(name), std::forward<A>(a)...); \
    }
#endif

#endif
